{"knowledge_entries":[
  {
    "intended_agents":["guide"],
    "name":"Überblick Transportzentrum",
    "source_object_ids":["object_001","object_002","object_003"],
    "tag":"transportzentrum",
    "text":"Das Transportzentrum ist ein Ausstellungsraum zur Geschichte und Technik des Verkehrs. Es gibt drei Sammlungsbereiche: Räder & Signalstationen, Fahrräder & Schienen sowie Brücken & Routen. Die Exponate sind als freistehende Displays in den jeweiligen Zonen angeordnet."
  },
  {
    "intended_agents":["guide"],
    "name":"Ausstellungsüberblick",
    "source_object_ids":["object_001","object_005","object_012"],
    "tag":"ausstellungsueberblick",
    "text":"Die Ausstellung gliedert sich in drei Zonen: Sammlung 1 (Räder & Signalstationen), Sammlung 2 (Fahrräder & Schienenmodelle) und Sammlung 3 (Brückenmodelle & Routenplanung). Jede Zone zeigt typische Exponate wie Rad- und Signaldisplays, Fahrrad- und Schienenmodelle sowie Brückenmodelle und Verkehrskarten."
  },
  {
    "intended_agents":["guide"],
    "name":"Navigation im Ausstellungsraum",
    "source_object_ids":["object_001","object_008","object_015"],
    "tag":"navigation",
    "text":"Die Sammlungen sind räumlich klar getrennt: Sammlung 1 befindet sich im linken Bereich, Sammlung 2 zentral und Sammlung 3 im rechten Bereich des Raumes. Die Exponate sind gut sichtbar und entlang der jeweiligen Zone angeordnet."
  },
  {
    "intended_agents":["guide"],
    "name":"Vernetzung der Themen",
    "source_object_ids":["object_004","object_005","object_006"],
    "tag":"vernetzung",
    "text":"Die Themen der Sammlungen sind miteinander verknüpft: Räder und Signalstationen bilden die Grundlage für Fahrräder und Schienenmodelle, während Brückenmodelle und Routenplanung zeigen, wie Verkehrswege entstehen und verbunden werden."
  },
  {
    "intended_agents":["collection1_expert"],
    "name":"Räder – Technik und Bedeutung",
    "source_object_ids":["object_001","object_007","object_013"],
    "tag":"raeder",
    "text":"In Sammlung 1 zeigen Rad-Displays wie object_001, object_007 und object_013 die technische Entwicklung und Funktionsweise von Rädern als zentrales Element des Transports."
  },
  {
    "intended_agents":["collection1_expert"],
    "name":"Signalstationen – Steuerung des Verkehrs",
    "source_object_ids":["object_004","object_010"],
    "tag":"signalstationen",
    "text":"Signalstationen wie object_004 und object_010 demonstrieren, wie der Verkehr durch Signale sicher und effizient gesteuert wird. Sie sind in Sammlung 1 zu finden."
  },
  {
    "intended_agents":["collection1_expert"],
    "name":"Technikgeschichte im Verkehr",
    "source_object_ids":["object_001","object_004","object_007"],
    "tag":"technikgeschichte",
    "text":"Die Exponate in Sammlung 1 veranschaulichen die historische Entwicklung von Rädern und Signalstationen und deren Einfluss auf die Verkehrstechnik."
  },
  {
    "intended_agents":["collection2_expert"],
    "name":"Fahrradtechnik – Innovationen im Detail",
    "source_object_ids":["object_002","object_008","object_014"],
    "tag":"fahrradtechnik",
    "text":"Fahrraddisplays wie object_002, object_008 und object_014 in Sammlung 2 erklären technische Besonderheiten und Innovationen im Fahrradbau."
  },
  {
    "intended_agents":["collection2_expert"],
    "name":"Schienenmodelle – Aufbau und Funktion",
    "source_object_ids":["object_005","object_011"],
    "tag":"schienenmodelle",
    "text":"Schienenmodelle wie object_005 und object_011 zeigen in Sammlung 2 den Aufbau und die Funktionsweise von Schienensystemen im Verkehr."
  },
  {
    "intended_agents":["collection2_expert"],
    "name":"Verkehrsgeschichte – Entwicklung der Mobilität",
    "source_object_ids":["object_002","object_005","object_008"],
    "tag":"verkehrsgeschichte",
    "text":"Die Fahrrad- und Schienenexponate in Sammlung 2 verdeutlichen die Entwicklung der Mobilität und deren Bedeutung für die Gesellschaft."
  },
  {
    "intended_agents":["collection3_expert"],
    "name":"Brückenbau – Modelle und Prinzipien",
    "source_object_ids":["object_003","object_009","object_015"],
    "tag":"brueckenbau",
    "text":"Brückenmodelle wie object_003, object_009 und object_015 in Sammlung 3 zeigen verschiedene Bauweisen und erklären die Prinzipien des Brückenbaus im Verkehrsbereich."
  },
  {
    "intended_agents":["collection3_expert"],
    "name":"Routenplanung – Wege im Verkehr",
    "source_object_ids":["object_006","object_012"],
    "tag":"routenplanung",
    "text":"Routenplanungsdisplays wie object_006 und object_012 in Sammlung 3 veranschaulichen, wie Verkehrswege geplant und optimiert werden."
  },
  {
    "intended_agents":["collection3_expert"],
    "name":"Verkehrskarten – Orientierung und Planung",
    "source_object_ids":["object_006","object_012"],
    "tag":"verkehrskarten",
    "text":"Verkehrskarten an den Displays object_006 und object_012 helfen, Verkehrsnetze zu verstehen und die Planung von Routen nachzuvollziehen."
  }
]}
